//! DI registration helpers for the transactional outbox.
//!
//! The application owns the database registration: call rust-ef's `add_dbcontext`
//! (or `add_dbcontext_keyed`), add the outbox entity to the model with
//! [`register_outbox_model`](crate::register_outbox_model), then call
//! [`add_outbox`](OutboxServiceCollectionExt::add_outbox). Migrations for the
//! outbox table are generated by the official rust-ef tooling; this crate never
//! creates schema at runtime and declares no routes.

use std::sync::Arc;

use rust_dix::{IServiceResolver, ScopeFactory, ServiceCollection};
use webx_core::route::ext::IServiceCollectionExt;
use webx_host::server::HostBuilder;

use crate::ef_outbox::EfOutbox;
use crate::options::OutboxOptions;
use crate::port::IOutbox;
use crate::worker::OutboxDispatcher;

/// Register the outbox port and its dispatcher on a [`ServiceCollection`].
pub trait OutboxServiceCollectionExt: Sized {
    /// Register `Arc<dyn IOutbox>` and, when `options.enabled`, the
    /// [`OutboxDispatcher`] background service.
    ///
    /// Requires a scoped rust-ef `DbContext` registered with `add_dbcontext`; the
    /// outbox resolves an owned context from a fresh DI scope per operation.
    fn add_outbox(self, options: OutboxOptions) -> Self;
}

impl OutboxServiceCollectionExt for ServiceCollection {
    fn add_outbox(self, options: OutboxOptions) -> Self {
        let max_attempts = options.max_attempts();
        let mut services = self.try_add_singleton::<dyn IOutbox>(move |resolver| {
            let services = resolve_scope_factory(resolver);
            Arc::new(EfOutbox::new(services, max_attempts)) as Arc<dyn IOutbox>
        });

        let worker_options = options.clone();
        services = services.add_background_service_with_if::<OutboxDispatcher, _>(
            options.enabled,
            move |resolver| {
                let services = resolve_scope_factory(resolver);
                let provider = resolver.provider_arc().expect(
                    "rust-dix built-in ScopeFactory implies a built provider; outbox registration \
                     requires a provider built by rust-dix",
                );
                Arc::new(OutboxDispatcher::new(
                    services,
                    provider,
                    worker_options.clone(),
                ))
            },
        );
        services
    }
}

/// Register the outbox on a [`HostBuilder`] (`add_outbox(...)`).
pub trait OutboxHostBuilderExt: Sized {
    /// Register the outbox port and (when enabled) the dispatcher.
    fn add_outbox(self, options: OutboxOptions) -> Self;
}

impl OutboxHostBuilderExt for HostBuilder {
    fn add_outbox(self, options: OutboxOptions) -> Self {
        self.register(move |services| services.add_outbox(options))
    }
}

/// The rust-dix built-in `ScopeFactory` is always resolvable from a built
/// provider; a failure here means the provider was built by hand without it.
fn resolve_scope_factory(resolver: &dyn IServiceResolver) -> Arc<dyn ScopeFactory> {
    rust_dix::IServiceResolverExt::resolve_arc::<dyn ScopeFactory>(resolver).expect(
        "rust-dix always provides the built-in Arc<dyn ScopeFactory>; \
         outbox registration requires a provider built by rust-dix",
    )
}
